import{_ as t,o as r,c as n,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Secure Token Service in Ceph - Pritha Srivastava, IBM","description":"","frontmatter":{"title":"Secure Token Service in Ceph - Pritha Srivastava, IBM","date":"2023-05-15T00:00:00.000Z","updated":"2023-05-16T00:00:00.000Z","tags":["Ceph","Security Token Service (STS)","RGW","Access Control","Authentication"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Secure_Token_Service_in_Ceph_-_Pritha_Srivastava_IBM.md","filePath":"posts/2023/Secure_Token_Service_in_Ceph_-_Pritha_Srivastava_IBM.md","lastUpdated":1780459816000}'),o={name:"posts/2023/Secure_Token_Service_in_Ceph_-_Pritha_Srivastava_IBM.md"};function s(a,e,S,l,_,p){return r(),n("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph中Secure Token Service (STS)在RGW中的应用</p><p><strong>主讲人：</strong> Pritha Srivastava，IBM Safe RGW团队开发人员</p><p><strong>会议内容概述：</strong> Pritha Srivastava介绍了STS在Ceph RGW中的应用，包括其基本概念、构建块、支持的API、自定义凭证提供者、ABAC授权策略以及在多站点环境中的实现。</p><p><strong>关键细节：</strong></p><ol><li><strong>STS简介：</strong> STS是一组API，提供临时且有限的凭证，类似于AWS STS。SDS（Security Domain Service）用于跨账户访问和集成外部应用，这些应用拥有大量用户且不希望拥有永久S3凭证。</li><li><strong>当前支持：</strong> RGW支持STS API的子集，包括AssumeRole、AssumeRoleWithWebIdentity和GetSessionToken。还实现了AWS IAM API的子集，用于角色、策略和OpenID Connect提供者的CRUD操作。</li><li><strong>临时凭证：</strong> 临时凭证包括访问密钥ID、秘密访问密钥和会话令牌。会话令牌加密，包含认证和授权信息。</li><li><strong>角色与策略：</strong> 角色是一个实体，类似于用户但没有永久S3凭证。角色关联两个IAM策略：信任策略（描述谁可以假设角色）和权限策略（描述角色可以做什么）。</li><li><strong>支持的API：</strong><ul><li><strong>AssumeRole：</strong> 提供跨账户或跨租户访问。</li><li><strong>AssumeRoleWithWebIdentity：</strong> 提供Web身份联合，用户通过OpenID Connect兼容提供者认证后，可以访问S3资源。</li></ul></li><li><strong>ABAC授权策略：</strong> 基于属性的访问控制（ABAC）使用标签（键值对）来定义权限，简化权限集的定义。</li><li><strong>STS Lite：</strong> 基于GetSessionToken API，主要用于外部认证如Keystone和LDAP，减少对Keystone服务器的延迟和负载。</li><li><strong>自定义凭证提供者：</strong> 一个Java模块，改进AWS SDK中的Web身份令牌凭证提供者，支持会话持续时间和会话策略，并提供刷新令牌功能。</li><li><strong>多站点实现：</strong> 角色和策略元数据复制已实现，OpenID Connect提供者元数据复制仍在进行中。</li></ol><p><strong>决定事项：</strong></p><ul><li>STS在RGW中的实现和功能已基本明确，多站点元数据复制功能已部分实现。</li></ul><p><strong>后续行动计划：</strong></p><ul><li>完善OpenID Connect提供者元数据复制功能。</li><li>探索和优化从桶策略到使用角色的性能改进。</li></ul><p><strong>参考资料：</strong></p><ul><li>STS及其相关主题的文档和GitHub仓库链接。</li></ul><p><strong>会议结束：</strong> Pritha感谢大家的参与，并邀请提问。会议中讨论了多站点配置、性能改进和与其他IDP的兼容性问题。</p><p>[Applause]</p>',14)])])}const u=t(o,[["render",s]]);export{g as __pageData,u as default};
